using GH_Net.Core.Enums;using GH_Net.Licensing;using GH_Net.Repository.Abstractions;using GH_Net.Repository.Data;using GH_Net.Repository.Entities;using GH_Net.Service.Abstractions;using GH_Net.Service.Implements;using Microsoft.Data.Sqlite;using Microsoft.EntityFrameworkCore;
string path=Path.Combine(Path.GetTempPath(),$"ghnet-app-{Guid.NewGuid():N}.db"),cs=$"Data Source={path}";try{await using(var db=PrinterManagerDbContext.Create(cs)){await db.Database.MigrateAsync();db.Jobs.Add(new Job{Name="Packing",ProductsPerCarton=2,CartonsPerPallet=2,TotalData=1});await db.SaveChangesAsync();}var factory=new UnitOfWorkFactory(cs);using var uow=factory.Create();var jobs=new JobService(uow);foreach (var features in new[] { LicenseFeature.Printer | LicenseFeature.Camera, (LicenseFeature)15 }) {
    var rejectedRuntime = new FakeRuntime();
    using var rejected = new JobRuntimeCoordinator(jobs, rejectedRuntime, new FakeScannerConfig(), new FakePrinterConfig(), new FakeScanner(), new FakePrinter(), new FakeLicense(features), new ZplTemplateRenderer());
    await AssertThrowsAsync<InvalidOperationException>(() => rejected.StartAsync(1), "Camera/legacy Base license must not authorize the scanner.");
    Assert(!rejectedRuntime.Started && rejected.ActiveJobId is null, "Denied scanner license started the runtime.");
}var runtime=new FakeRuntime();var coordinator=new JobRuntimeCoordinator(jobs,runtime,new FakeScannerConfig(),new FakePrinterConfig(),new FakeScanner(),new FakePrinter(),new FakeLicense(),new ZplTemplateRenderer());await coordinator.StartAsync(1);Assert(coordinator.CurrentStatus==JobStatus.Running&&runtime.Started,"Coordinator must start packing runtime.");await coordinator.StopAsync();Assert(coordinator.CurrentStatus==JobStatus.Paused&&runtime.Stopped,"Coordinator must stop packing runtime.");await using(var db=PrinterManagerDbContext.Create(cs)){var job=await db.Jobs.SingleAsync();job.Status=JobStatus.Running;job.PackingWorkflowState=PackingWorkflowState.CartonWaitingConfirmation;await db.SaveChangesAsync();}using var recoveryUow=factory.Create();await new JobService(recoveryUow).RecoverCrashedJobsAsync();await using(var db=PrinterManagerDbContext.Create(cs)){var recovered=await db.Jobs.SingleAsync();Assert(recovered.Status==JobStatus.Paused,"Crash recovery must pause the Job.");Assert(recovered.PackingWorkflowState==PackingWorkflowState.CartonWaitingConfirmation,"Crash recovery must preserve the packing workflow.");}var invalid=new JobRuntimeCoordinator(jobs,new FakeRuntime(),new FakeScannerConfig(),new FakePrinterConfig("^XA^FDNO_PLACEHOLDER^FS^XZ"),new FakeScanner(),new FakePrinter(),new FakeLicense(),new ZplTemplateRenderer());await AssertThrowsAsync<InvalidOperationException>(()=>invalid.StartAsync(1),"Start must reject an invalid ZPL template.");Console.WriteLine("Packing application smoke passed: coordinator start/stop, ZPL validation and workflow-preserving recovery.");}finally{SqliteConnection.ClearAllPools();if(File.Exists(path))File.Delete(path);}static void Assert(bool ok,string msg){if(!ok)throw new InvalidOperationException(msg);}static async Task AssertThrowsAsync<T>(Func<Task> action,string msg)where T:Exception{try{await action();}catch(T){return;}throw new InvalidOperationException(msg);}
sealed class FakeRuntime:IPackingRuntimeService{public int? ActiveJobId{get;private set;}public bool IsRunning=>Started&&!Stopped;public bool IsBusy=>false;public bool Started{get;private set;}public bool Stopped{get;private set;}public PackingRuntimeSnapshot? Current=>null;public event EventHandler<PackingRuntimeSnapshot>? SnapshotChanged;public event EventHandler<Exception>? RuntimeFailed;public Task StartAsync(int id,CancellationToken ct=default){ActiveJobId=id;Started=true;return Task.CompletedTask;}public Task StopAsync(CancellationToken ct=default){Stopped=true;return Task.CompletedTask;}public Task HandleScanAsync(string c,CancellationToken ct=default)=>Task.CompletedTask;public Task RetryPrintAsync(CancellationToken ct=default)=>Task.CompletedTask;}
